 function setup(){shell(`<form id="recSetup"><div class="settings-grid"><label class="field">目标歌曲<select id="recSong">${songs.map(s=>`<option value="${h.esc(s.id)}">${h.esc(s.title)}</option>`).join('')}<option value="new">＋ 新建歌曲</option></select></label><label class="field">新歌曲名称<input id="recTitle" maxlength="120" placeholder="新建时必填"></label><label class="field">难度分类<select id="recTier">${C.LEVELS.map((s,i)=>`<option value="${i}" ${i===3?'selected':''}>${s.name}</option>`).join('')}</select></label><label class="field">难度值<input id="recLevel" type="number" min="0" max="100" value="17" required step="any"></label><label class="field">歌曲音频<input id="recAudio" type="file" accept="audio/*,.ogg"><small>现有歌曲可沿用音频；新建或原音频缺失时必传</small></label><label class="field">手谱视频<input id="recVideo" type="file" accept="video/*,.mp4,.webm,.mov" required><small>自动读取 MP4 原始帧率；视频可无声</small></label></div><details><summary>高级：手动覆盖帧率（通常留空）</summary><label class="field">帧率覆盖<input id="recFPS" type="number" min="10" max="120" step=".001" placeholder="自动测算"><small>仅自动识别失败或元数据不正确时填写</small></label></details><p class="account-note">流速在模板确认后，从 10 个音符轨迹自动取平均，此处无需填写。仅支持经典六键、无停流 / 倒流 / SV 的视频。正常机台残影会参与容错分析。尽量正对完整屏幕，固定镜头，避免遮挡、画面抖动、模糊与强反光。使用与本站默认皮肤相近的皮肤。低分辨率或严重透视无法保证识别。</p><label class="check-line"><input id="recClassic" type="checkbox" required> 确认视频为经典 6Key 且无变速效果</label><button id="recContinue" type="submit" class="primary">自动测帧率并粗分析 →</button></form>`);$('recSong').value=state.songId;$('recSetup').onsubmit=e=>{e.preventDefault();if(busy)return;job(async()=>{const file=$('recVideo').files[0],audio=$('recAudio').files[0],override=$('recFPS').value.trim()?+$('recFPS').value:null;state.songId=$('recSong').value;state.title=$('recTitle').value.trim();state.level=+$('recLevel').value;state.tier=+$('recTier').value;if(state.songId==='new'&&!state.title)throw Error('请填写新歌曲名称');if(!file||file.size>2*1024**3)throw Error('请选择不超过 2 GB 的本地视频');if(!Number.isFinite(state.level)||state.level<0||state.level>100||override!==null&&(!Number.isFinite(override)||override<10||override>120))throw Error('难度或帧率覆盖无效');if(audio){if(audio.size>200*1024**2)throw Error('音频不能超过 200 MB');state.audio={name:audio.name,mime:audio.type,data:new Uint8Array(await audio.arrayBuffer())};}else state.audio=h.audio(state.songId);if(!state.audio)throw Error('所选歌曲没有可用音频，请上传音频');check();$('recContinue').disabled=true;state.videoFile=file;bank=[];state.speedInfo=null;video?.close();vision?.close();video=new LocalVideo(file);await video.open();check();progress(0,'正在读取原视频帧率…');const measured=await video.frameRate(file,controller.signal);check();state.fpsInfo=override!==null?{...measured,fps:override,method:'手动覆盖（原测量 '+(measured?.fps?.toFixed(3)||'未知')+'）'}:measured;if(!state.fpsInfo)throw Error('无法自动测算该编码的帧率，请展开高级设置手动填写后重试');state.fps=state.fpsInfo.fps;if(state.fps<10||state.fps>120)throw Error('当前支持 10～120 FPS');templates=await skinTemplates();check();vision=new Vision();await coarse();});};}
 async function coarse(){controlsPause();const times=[],count=Math.max(64,Math.min(128,Math.ceil(video.el.duration*4))),w=video.canvas.width,h=video.canvas.height,background=new Float32Array(w*h*4);edge=new Float32Array(w*h);for(let i=0;i<count;i++){await checkpoint();const t=(i+.28+.44*((i*.61803398875)%1))/count*video.el.duration,read=await video.frame(t,controller.signal),e=R.edges(read.frame);for(let k=0;k<edge.length;k++)edge[k]+=e[k]/count;for(let k=0;k<background.length;k++)background[k]+=read.frame.data[k]/count;times.push(t);progress(i/count*40,`全片粗扫 ${i+1}/${count} · ${state.fps.toFixed(3)} FPS · ${t.toFixed(1)} 秒`);}geometry=await vision.call('geometry',{edge:edge.buffer,width:w,height:h},[edge.buffer]);const data=new Uint8ClampedArray(background);await vision.call('background',{frame:{width:w,height:h,data}},[data.buffer]);state.coarseTimes=times;await findSamples();step=1;calibration();}
